
SELECT 'staging.dataco_raw' AS table_name, j.key AS column_name, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb) AS null_count, COUNT(*) AS total_rows FROM staging.dataco_raw t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'staging.olist_customers_raw', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM staging.olist_customers_raw t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.customers_dataco', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.customers_dataco t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.inventory_master', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.inventory_master t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.inventory_snapshots', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.inventory_snapshots t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.olist_customers', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.olist_customers t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.order_items', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.order_items t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.orders', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.orders t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.product_suppliers', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.product_suppliers t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.products', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.products t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.supplier_performance', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.supplier_performance t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'core.suppliers', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM core.suppliers t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'analytics.dim_customer_dataco', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM analytics.dim_customer_dataco t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'analytics.dim_date', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM analytics.dim_date t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'analytics.dim_geography', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM analytics.dim_geography t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'analytics.dim_product', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM analytics.dim_product t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key UNION ALL SELECT 'analytics.fact_order_items', j.key, COUNT(*) FILTER (WHERE j.value = 'null'::jsonb), COUNT(*) FROM analytics.fact_order_items t CROSS JOIN LATERAL jsonb_each(to_jsonb(t)) j GROUP BY j.key ORDER BY table_name, column_name;
